SELECT
    DATE(start_date) AS day,
    SUM(distance) AS daily_distance
FROM drives
WHERE car_id = #{carId}
  AND start_date >= #{startDate}
  AND start_date < #{endDate}
GROUP BY DATE(start_date)

SELECT DISTINCT DATE(date)
FROM charges
WHERE  date >= #{startDate}
  AND date < #{endDate}
